productConfig.customStyles:
/* Inter — served from a public CDN with Access-Control-Allow-Origin: * (Sprig CS requirement).
   Blocked in the Sprig dashboard PREVIEWER by design; loads fine in deployed Dev/Prod surveys. */
@font-face { font-family: 'Inter'; font-style: normal; font-weight: 400; font-display: swap;
  src: url('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-400-normal.woff2') format('woff2'),
       url('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-400-normal.woff') format('woff'); }
@font-face { font-family: 'Inter'; font-style: normal; font-weight: 500; font-display: swap;
  src: url('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-500-normal.woff2') format('woff2'),
       url('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-500-normal.woff') format('woff'); }
@font-face { font-family: 'Inter'; font-style: normal; font-weight: 600; font-display: swap;
  src: url('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-600-normal.woff2') format('woff2'),
       url('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-600-normal.woff') format('woff'); }
@font-face { font-family: 'Inter'; font-style: normal; font-weight: 700; font-display: swap;
  src: url('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-700-normal.woff2') format('woff2'),
       url('https://cdn.jsdelivr.net/npm/@fontsource/inter@5/files/inter-latin-700-normal.woff') format('woff'); }

/* ============================================================
   Retool brand theme for Sprig surveys
   Tokens: Toolbox design system (retool_development)
   DOM-verified against the live Sprig preview (360px overlay).
   Iterate by editing the :root tokens below.
   ============================================================ */

:root {
  --rt-font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,
    'Helvetica Neue', Arial, sans-serif;

  /* Brand / accent */
  --rt-brand: #3170f9;         /* blue-600 */
  --rt-brand-hover: #1d4ed8;   /* blue-700 */
  --rt-brand-tint: #e5f1ff;    /* blue-100 */
  --rt-brand-tint-weak: #f5f9ff;

  /* Neutrals (Toolbox light) */
  --rt-gray-50: #f9f9f9;
  --rt-gray-100: #f6f6f6;
  --rt-gray-200: #dfdfdf;
  --rt-gray-300: #c7c7c7;
  --rt-gray-400: #b3b3b3;
  --rt-gray-500: #999999;
  --rt-gray-600: #808080;
  --rt-gray-700: #555555;
  --rt-gray-800: #222222;
  --rt-gray-900: #0d0d0d;

  --rt-red-600: #dc2626;

  /* Semantic */
  --rt-text: var(--rt-gray-900);
  --rt-text-secondary: var(--rt-gray-700);   /* AA on white */
  --rt-text-placeholder: var(--rt-gray-500);
  --rt-surface: #ffffff;
  --rt-border: var(--rt-gray-200);
  --rt-border-strong: var(--rt-gray-300);
  --rt-hover: var(--rt-gray-100);
  --rt-focus-ring: rgba(96, 165, 250, 0.4);

  /* Radius */
  --rt-radius-sm: 6px;
  --rt-radius-md: 8px;
  --rt-radius-lg: 12px;

  /* Elevation */
  --rt-shadow-card: 0 1px 2px rgba(13, 13, 13, 0.04), 0 6px 20px rgba(13, 13, 13, 0.08);

  /* Motion */
  --rt-ease: cubic-bezier(0.2, 0, 0, 1);
  --rt-dur: 120ms;

  /* Gutter delta: added to the shared parent so every section stays aligned.
     4px = 20px gutter · 8px = 24px gutter */
  --rt-gutter-delta: 4px;
}

/* ---------- Typography — Sprig CS's high-specificity pattern, robust to
   the .ul-card__container--desktop / _inPr class variants ---------- */
html body [class*="ul-card__container"],
html body [class*="ul-card__container"] * {
  font-family: var(--rt-font-sans) !important;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

b { font-weight: 600; }

/* ---------- Padding / alignment (DOM-verified) ---------- */
/* All sections live inside .ul-card-main-content (side padding 0). Adding the
   delta here widens the gutter equally for every section — never misaligns. */
.ul-card-main-content,
.ul-card-main-content__web {
  padding-left: var(--rt-gutter-delta) !important;
  padding-right: var(--rt-gutter-delta) !important;
}
/* Question fills width (removes the reserved right-slot asymmetry) */
.ul-question,
.question-header-button-container { width: 100% !important; }
.question-header-container,
.sprig-header-container { padding: 24px 16px 12px !important; }

/* ---------- Card ---------- */
.ul-card,
.ul-card__container { border-radius: var(--rt-radius-lg); background: var(--rt-surface); }
.ul-card__container--desktop { box-shadow: var(--rt-shadow-card); }

/* ---------- Question & caption ---------- */
.ul-question {
  color: var(--rt-text);
  font-size: 20px;
  line-height: 28px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.ul-caption {
  color: var(--rt-text-secondary);
  font-size: 15px;
  line-height: 24px;
  letter-spacing: normal;
  margin: 6px 0 16px;
}
.ul-rich-text-body p,
.ul-rich-text-body li {
  color: var(--rt-gray-800);
  font-size: 15px;
  line-height: 24px;
  letter-spacing: normal;
}
.ul-rich-text-body a { color: var(--rt-brand); text-underline-offset: 2px; }

/* ---------- Primary button (Retool blue; !important beats Sprig inline) ---------- */
.ul-card-text__button:not(.ul-card-skip__button) {
  background-color: var(--rt-brand) !important;
  color: #ffffff !important;
  border: none;
  border-radius: var(--rt-radius-sm);
  font-size: 15px;
  font-weight: 600;
  line-height: 24px;
  padding: 8px 21px;
  cursor: pointer;
  transition: background-color var(--rt-dur) var(--rt-ease), box-shadow var(--rt-dur) var(--rt-ease);
}
.ul-card-text__button:not(.ul-card-skip__button):hover:not(:disabled) {
  background-color: var(--rt-brand-hover) !important;
}
.ul-card-text__button:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--rt-surface), 0 0 0 4px var(--rt-brand);
}
.ul-card-text__button:disabled {
  background-color: var(--rt-gray-200) !important;
  color: var(--rt-gray-500) !important;
  cursor: not-allowed;
}
/* Skip = secondary */
.ul-card-skip__button {
  background-color: var(--rt-surface) !important;
  color: var(--rt-text-secondary) !important;
  border: 1px solid var(--rt-border) !important;
}
.ul-card-skip__button:hover:not(:disabled) {
  background-color: var(--rt-hover) !important;
  color: var(--rt-text) !important;
}

/* ---------- Choices (multi / single / consent) ---------- */
.choice {
  color: var(--rt-text);
  border-radius: var(--rt-radius-sm);
  background-color: var(--rt-surface);
  box-sizing: border-box;
  transition: background-color var(--rt-dur) var(--rt-ease),
    border-color var(--rt-dur) var(--rt-ease), box-shadow var(--rt-dur) var(--rt-ease);
}
.choice--desktop { border: 1px solid var(--rt-border); }
.choice--mobile  { border: 2px solid var(--rt-border); }
.choice--desktop:hover { background-color: var(--rt-hover); border-color: var(--rt-border-strong); }
.choice--desktop:active, .choice--mobile:active {
  background-color: var(--rt-brand-tint-weak); border-color: var(--rt-brand);
}
.choice:focus-visible {
  outline: none; border-color: var(--rt-brand); box-shadow: 0 0 0 3px var(--rt-focus-ring);
}
/* Selected state */
.ul-select-active-dynamic-style.choice,
.choice.is-selected,
.choice[aria-checked='true'] {
  border-color: var(--rt-brand) !important;
  background-color: var(--rt-brand-tint) !important;
}

/* ---------- Radio / checkbox indicator ----------
   Extra specificity (html body [class*="ul-card__container"]) to beat Sprig's
   runtime !important rules that load after our stylesheet. */
html body [class*="ul-card__container"] .select-radio {
  flex-shrink: 0;
  border: 1px solid var(--rt-gray-400) !important;   /* unselected: neutral gray ring */
  background: transparent !important;
}
html body [class*="ul-card__container"] .ul-select-active-dynamic-style .select-radio {
  border: 1px solid var(--rt-brand) !important;      /* selected: brand ring + filled dot */
  background: radial-gradient(circle at center,
    var(--rt-brand) 0 34%, #ffffff 38% 100%) !important;
}

/* ---------- Likert / NPS scales ---------- */
/* No overflow clipping — round the end cells instead (fixes cut-off ends) */
.ul-card--likert__numbers,
.ul-card--nps__numbers { border-radius: var(--rt-radius-md); overflow: visible !important; }
.likert-number, .nps-number {
  background-color: var(--rt-surface);
  color: var(--rt-text);
  font-size: 18px;
  line-height: 24px;
  transition: background-color var(--rt-dur) var(--rt-ease), color var(--rt-dur) var(--rt-ease);
}
.likert-number--desktop, .nps-number--desktop { border: 1px solid var(--rt-border); }
.likert-number--mobile, .nps-number--mobile { border: 2px solid var(--rt-border); }
.likert-number:first-child, .nps-number:first-child {
  border-top-left-radius: var(--rt-radius-md); border-bottom-left-radius: var(--rt-radius-md);
}
.likert-number:last-child, .nps-number:last-child {
  border-top-right-radius: var(--rt-radius-md); border-bottom-right-radius: var(--rt-radius-md);
}
.likert-number--desktop:hover, .nps-number--desktop:hover {
  background-color: var(--rt-hover); font-weight: 600;
}
.likert-number:active, .nps-number:active {
  background-color: var(--rt-brand-tint); border-color: var(--rt-brand);
  color: var(--rt-brand-hover); font-weight: 600; z-index: 2;
}
.likert-number:focus-visible, .nps-number:focus-visible {
  outline: none; z-index: 3; box-shadow: inset 0 0 0 2px var(--rt-brand);
}
.ul-card--likert__labels, .ul-card--nps__labels {
  color: var(--rt-text-secondary); font-weight: 500; font-size: 13px; line-height: 20px; margin: 7px 0 10px;
}

/* ---------- Text & consent inputs ---------- */
/* Constant 1px border in every state → no reflow while typing.
   !important beats Sprig's dark default focus border/shadow. */
.ul-card-text__input,
.ul-card-text__input--desktop,
.ul-card-text__input--mobile,
.ul-consent-legal__name-input,
.ul-consent-legal__name-input--desktop,
.ul-consent-legal__name-input--mobile {
  border: 1px solid var(--rt-border-strong) !important;
  border-radius: var(--rt-radius-sm) !important;
  box-shadow: none !important;
  background: var(--rt-surface);
  color: var(--rt-text);
  font-size: 15px;
  line-height: 24px;
  transition: border-color var(--rt-dur) var(--rt-ease), box-shadow var(--rt-dur) var(--rt-ease),
    background-color var(--rt-dur) var(--rt-ease);
}
.ul-card-text__input::placeholder,
.ul-consent-legal__name-input::placeholder { color: var(--rt-text-placeholder); }
.ul-card-text__input:focus,
.ul-consent-legal__name-input:focus {
  outline: none !important;
  border: 1px solid var(--rt-brand) !important;
  box-shadow: 0 0 0 3px var(--rt-focus-ring) !important;
  background: var(--rt-surface);
}
.ul-card-text__input--desktop:hover:not(:focus),
.ul-consent-legal__name-input--desktop:hover:not(:focus) {
  border-color: var(--rt-gray-400) !important; background-color: var(--rt-gray-50);
}

/* ---------- Rank order ---------- */
.ul-card-rank__option {
  border: 1px solid var(--rt-border); border-radius: var(--rt-radius-md); background: var(--rt-surface);
  transition: border-color var(--rt-dur) var(--rt-ease), box-shadow var(--rt-dur) var(--rt-ease);
}
.ul-card-rank__option.is-dragging {
  border-color: var(--rt-brand);
  box-shadow: 0 8px 25px rgba(13,13,13,0.12), 0 3px 10px rgba(13,13,13,0.08);
}
.ul-card-rank__option.is-drop-target { background: var(--rt-brand-tint); border-color: var(--rt-brand); }
.ul-card-rank__drag-btn { color: var(--rt-gray-700); border-radius: var(--rt-radius-sm); }
.ul-card-rank__drag-btn:hover { color: var(--rt-text); background: var(--rt-hover); }
.ul-card-rank__select {
  border: 1px solid var(--rt-border-strong); border-radius: var(--rt-radius-sm); color: var(--rt-text);
}
.ul-card-rank__select:focus-visible {
  outline: none; border-color: var(--rt-brand); box-shadow: 0 0 0 3px var(--rt-focus-ring);
}

/* ---------- Footer / progress dots / close ---------- */
.ul-footer-bubble { background-color: var(--rt-gray-300); border-radius: 999px; transition: background-color var(--rt-dur) var(--rt-ease); }
.ul-footer-bubble--active, .ul-footer-bubble.is-active { background-color: var(--rt-brand) !important; }
.close-btn { color: var(--rt-gray-600); border-radius: var(--rt-radius-sm); transition: color var(--rt-dur) var(--rt-ease); }
.close-btn:hover { color: var(--rt-gray-800); }
.close-btn:focus-visible { outline: 2px solid var(--rt-brand); outline-offset: 2px; }

/* ---------- Thank-you ---------- */
.ul-thanks-check { color: var(--rt-brand); }

/* ---------- Accessibility: reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  .ul-footer-bubble, .choice, .likert-number, .nps-number,
  .ul-card-text__input, .ul-consent-legal__name-input, .ul-card-text__button,
  .ul-card-rank__option, .ul-card-rank__select, .close-btn { transition: none !important; }
  .ul-card-text__input__loading { animation: none !important; }
}
